<script setup>
import {onMounted,ref} from 'vue';import {api} from '../api';
const f=ref({companyName:'',contactName:'',email:'',requestedWarehouseId:'',requestedSqft:1000,spaceType:'GENERAL',requestedStart:'',termMonths:12,cargoProfile:[],notes:''});
const cargos=['GENERAL','FRAGILE','COLD_CHAIN','HIGH_VALUE','MEDICAL','FOOD','HAZARDOUS','OVERSIZED'];const submitted=ref(false),result=ref(null),warehouses=ref([]),busy=ref(false),error=ref('');
function toggle(x){const a=f.value.cargoProfile;a.includes(x)?a.splice(a.indexOf(x),1):a.push(x)}
async function load(){try{warehouses.value=(await api.get('/marketplace/warehouses')).data;if(!f.value.requestedWarehouseId)f.value.requestedWarehouseId=warehouses.value[0]?.id||''}catch{}}
async function submit(){error.value='';if(!f.value.companyName||!f.value.contactName||!f.value.email||!f.value.requestedWarehouseId){error.value='Please complete the company, contact, email and preferred warehouse fields.';return}busy.value=true;try{result.value=(await api.post('/tenant-applications',f.value)).data;submitted.value=true}catch(e){error.value=e.response?.data?.error||'Unable to submit application.'}finally{busy.value=false}}
onMounted(load);
</script>
<template><div class="login"><div class="login-showcase"><div><div class="brand"><div class="brand-mark">FD</div><div><b>FlowDepot</b><span>Warehouse Network</span></div></div><h1>Apply for warehouse space digitally.</h1><p>Choose the warehouse and space profile you require. Your application enters the owner's controlled leasing workflow.</p></div><div class="digital-flow"><span>Application</span><b>→</b><span>Review</span><b>→</b><span>Offer</span><b>→</b><span>Lease</span><b>→</b><span>Onboarding</span></div></div><div class="login-panel"><div class="login-card" style="width:min(680px,100%)"><template v-if="!submitted"><h2>Warehouse tenancy application</h2><p>No account is required to submit an enquiry.</p><div class="form-grid"><div class="field"><label>Company</label><input v-model="f.companyName" placeholder="Company legal / trading name"></div><div class="field"><label>Contact person</label><input v-model="f.contactName" placeholder="Full name"></div><div class="field"><label>Email</label><input type="email" v-model="f.email" placeholder="name@company.com"></div><div class="field"><label>Preferred warehouse</label><select v-model="f.requestedWarehouseId"><option value="">Choose warehouse</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}} — {{w.siteName}} · {{w.address}}</option></select></div><div class="field"><label>Required space (sqft)</label><input type="number" min="1" v-model.number="f.requestedSqft"></div><div class="field"><label>Space type</label><select v-model="f.spaceType"><option value="GENERAL">General storage</option><option value="COLD_STORAGE">Cold storage</option><option value="FULFILMENT">Fulfilment</option><option value="HIGH_SECURITY">High security</option><option value="HAZMAT">Hazardous goods capable</option></select></div><div class="field"><label>Preferred start</label><input type="date" v-model="f.requestedStart"></div><div class="field"><label>Term</label><select v-model.number="f.termMonths"><option :value="6">6 months</option><option :value="12">12 months</option><option :value="24">24 months</option><option :value="36">36 months</option></select></div></div><div class="field section"><label>Cargo / operational profile</label><div class="chip-wrap"><button v-for="x in cargos" :key="x" type="button" :class="['handling-chip',{selected:f.cargoProfile.includes(x)}]" @click="toggle(x)">{{x.replaceAll('_',' ')}}</button></div></div><div class="field section"><label>Special requirements</label><textarea rows="5" v-model="f.notes" placeholder="Temperature range, loading requirements, certifications, security, operating hours, fit-out needs…"></textarea></div><div v-if="error" class="error">{{error}}</div><button class="btn section" :disabled="busy" @click="submit">{{busy?'Submitting…':'Submit application'}}</button> <a href="/login" style="margin-left:12px;font-size:12px">Existing tenant login</a></template><template v-else><h2>Application received</h2><p>Thank you. Your application reference is <b>{{result.id}}</b>. The warehouse owner can now review your requirements and contact you for the next step.</p><div class="callout">Status: {{result.status.replaceAll('_',' ')}}</div></template></div></div></div></template>
